function (vars) {
	var g  = new GridWidget(vars.element, vars.payments);
	g.editable = false;
	g.sortable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = false;
	g.groupable = false;
	g.commands.push({ name: "view", icon: "k-i-share", text: "[resource_shortdisplayname[View]]", href: "/Payments/Payment?Id=#:RemittanceAdviceId#" });
	g.columns = [
		{ field: "LineNumber", type: "number", title: "[resource_shortdisplayname[linenumber]]", width: 70 },
		{ field: "PaymentReference", type: "string", title: "[resource_shortdisplayname[paymentreference]]", },
		{ field: "Description", type: "string", title: "[resource_shortdisplayname[Description]]" },
		{ field: "LinePrice", type: "number", title: "[resource_shortdisplayname[LinePrice]]", attributes: { style: "text-align: right;" }, format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"}},
		{ field: "CurrencyId", type: "string", title: "[resource_shortdisplayname[CurrencyId]]", width: 70 },
		{ field: "LastUpdated", type: "date", title: "[resource_shortdisplayname[LastUpdated]]", format: "{0:" + type.dateFormat + "}", width: 110 },
	];
	vars.RelatedPaymentGrid = g;
}
